 --muted2:var(--muted-strong);--muted-2:var(--muted-strong);--positive:var(--up);--negative:var(--down);--theme-browser:var(--bg);
 background:var(--bg)!important;color:var(--text);
}
html:not([data-inj-page="index"]) body{background:var(--page-gradient),var(--bg)!important;color:var(--text);overscroll-behavior:none!important}
