html[data-inj-viewport] .live-page,html[data-inj-viewport] .book-page,html[data-inj-viewport] .cc-shell{
 height:var(--inj-viewport-height,100dvh)!important;min-height:0!important;max-height:none!important;overflow-x:hidden!important;overflow-y:auto!important;overscroll-behavior:none!important;
}
/* A single document scroller avoids an unscrollable body trapping wheel input. */
html:not([data-inj-page="index"]) body,html[data-inj-page]:not([data-inj-page="index"]) body{height:auto!important;overflow:visible!important}
/* Align the existing Home controls at one safe-area-aware top inset. */
