.treasury-header,.rewards-header{top:0!important}

/* Navigation sits on the page's own themed gradient, without a separate slab.
   In-flow headers scroll with their section so content cannot pass behind them. */
html[data-theme] body :is(.app-shell > .topbar,.treasury-header,.rewards-header,
 .terminal-header,.book-topbar,.cc-topbar,.converter-view-header,
