 -webkit-overflow-scrolling:touch;
 scrollbar-width:thin;
 padding:8px!important;
}
#themeControl.open #themePicker.theme-picker{
 display:block!important;
}
#themePicker .theme-category{
 margin:0 0 7px;
 padding:0;
 border:1px solid var(--line,rgba(255,255,255,.15));
 border-radius:12px;
 background:color-mix(in srgb,var(--surface,#172330) 80%,transparent);
 overflow:hidden;
}
#themePicker .theme-category:last-child{margin-bottom:0}
#themePicker .theme-category>summary{
 display:flex;align-items:center;justify-content:space-between;gap:8px;
 list-style:none;cursor:pointer;min-height:46px;
 padding:10px 11px;color:var(--text,#fff);
 font-weight:780;font-size:12px;letter-spacing:.025em;
 -webkit-tap-highlight-color:transparent;user-select:none;
}
#themePicker .theme-category>summary::-webkit-details-marker{display:none}
#themePicker .theme-category>summary::after{
 content:"›";font-size:20px;font-weight:500;color:var(--muted,#aaa);
 margin-left:3px;transform:rotate(0deg);transition:transform .18s ease;
}
#themePicker .theme-category[open]>summary::after{transform:rotate(90deg)}
#themePicker .theme-category[open]>summary{
 color:var(--accent,#fff);
}
#themePicker .theme-category>summary:focus-visible{
 outline:2px solid var(--accent,#fff);outline-offset:-2px;border-radius:10px;
}
