/* INJ Node v16.01.35 — canonical responsive navigation geometry.
 * ONE safe-area inset, ONE back control, ONE readable section title.
 * Replaces dashboard-livecharts-top, ios-top-alignment and
 * section-header-consistency; do not layer those patch stylesheets again.
 * Pure presentation: no scroll-state, data, chart or theme mutations. */
:root {
  --inj-header-back: 44px;
  --inj-header-gap: 10px;
  --inj-header-air: 8px;
  --inj-header-safe: max(8px,calc(env(safe-area-inset-top,0px) + var(--inj-header-air)));
  --inj-control-inset: var(--inj-header-safe);
}
/* Keep existing title localization and theme colors. */
.inj-location-title,.inj-location-brand {
  min-width:0!important;
  text-align:left!important;
  text-decoration:none!important;
}
.inj-location-title > .inj-location-name,
.inj-location-brand > .inj-location-name {
  display:block!important;white-space:nowrap!important;
}
.inj-location-title > .inj-location-section,
.inj-location-brand > .inj-location-section {
  display:block!important;white-space:nowrap!important;
}
/* Never leave Home lettering visually behind Dashboard.
   Transition underlays remain untouched until actually dismissed. */
html[data-inj-page="index"] body:not(.entry-gate-open):not(.dashboard-home-return):not(.entry-live-launch)
  > #entryGate[aria-hidden="true"]:not(.immersive-underlay):not(.dashboard-underlay),
html[data-inj-page="index"] body.dashboard-scroll-ready:not(.entry-gate-open)
  > #injHomeBrandFooter,
html[data-inj-page="index"] body:not(.boot-loading) > #bootSplash {
  display:none!important;visibility:hidden!important;pointer-events:none!important;
}
@media(max-width:900px) {
  /* A single source for iPhone and mobile web/PWA inset.
     Do not apply this a second time to the containing page. */
  :root{
    --inj-header-safe:max(10px,calc(env(safe-area-inset-top,0px) + 7px));
  }
  /* Shell padding previously counted the notch/status inset again. */
  html[data-inj-page="index"] body.dashboard-scroll-ready:not(.entry-gate-open) > .app-shell,
