html[data-inj-page="index"][data-theme="ocean-x-solar"]{--inj-native-status-tone:#51334f}

/* On mobile, the native status bar and the top pixel of Home now use
   the same palette tone. The gradient appears gradually, not as a seam. */
@media (max-width:900px),(hover:none) and (pointer:coarse){
 html[data-inj-page="index"][data-theme]{
  background-color:var(--inj-native-status-tone,var(--theme-canvas,#10272a))!important;
  background-image:
    linear-gradient(180deg,
      var(--inj-native-status-tone,var(--theme-canvas,#10272a)) 0px,
      color-mix(in srgb,var(--inj-native-status-tone,var(--theme-canvas,#10272a)) 94%,transparent) 18px,
