 --inj-chosen-face:"INJ Geist","Geist",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;
}
html[data-inj-font="slim"]{
 --inj-chosen-weight:300;
 --inj-chosen-detail:300;
 --inj-chosen-emphasis:400;
 --inj-chosen-heading:400;
}
html[data-inj-font="bold"]{
 --inj-chosen-weight:650;
 --inj-chosen-detail:600;
 --inj-chosen-emphasis:750;
 --inj-chosen-heading:800;
}
html[data-inj-font]{
 --inj-ui-font:var(--inj-chosen-face);
 --inj-minimal-font:var(--inj-chosen-face);
 --inj-minimal-mono:var(--inj-chosen-face);
 --inj-inter-light-font:var(--inj-chosen-face);
 --inj-node-terminal-font:var(--inj-chosen-face);
 --inj-home-title-face:var(--inj-chosen-face);
 --inj-home-description-face:var(--inj-chosen-face);
 --inj-editorial-face:var(--inj-chosen-face);
 font-family:var(--inj-chosen-face)!important;
 font-variant-numeric:tabular-nums lining-nums;
}
