/* A compact family accordion: only six previews at a time. */
#themePicker .inj-theme-family{margin:0 0 7px;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:color-mix(in srgb,var(--surface) 84%,transparent)}
#themePicker .inj-theme-family>summary{list-style:none;display:flex;align-items:center;gap:12px;min-height:58px;padding:11px 13px;cursor:pointer;color:var(--text);user-select:none}
#themePicker .inj-theme-family>summary::-webkit-details-marker{display:none}
#themePicker .inj-theme-family>summary .inj-family-illustration{flex:0 0 34px;width:34px;height:34px;border-radius:10px;display:grid;place-items:center;font-size:17px;background:color-mix(in srgb,var(--accent) 12%,var(--surface-strong));border:1px solid var(--line)}
#themePicker .inj-theme-family>summary .inj-family-title{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
#themePicker .inj-theme-family>summary .inj-family-title strong{font-size:12px;font-weight:650;line-height:1.35}
#themePicker .inj-theme-family>summary .inj-family-title small{font-size:10px;line-height:1.3;color:var(--muted)}
#themePicker .inj-theme-family>summary .inj-family-chevron{width:8px;height:8px;border-right:1.6px solid var(--muted-strong);border-bottom:1.6px solid var(--muted-strong);transform:rotate(45deg);transition:transform .2s}
#themePicker .inj-theme-family[open]>summary .inj-family-chevron{transform:rotate(225deg)}
#themePicker .inj-theme-family[open]>summary{border-bottom:1px solid var(--line)}
#themePicker .inj-theme-family>div.theme-list-unified{display:grid;grid-template-columns:1fr;gap:5px;padding:9px}
#themePicker .inj-theme-family>div.theme-list-unified>button{display:flex;align-items:center;gap:13px;width:100%;min-height:63px;padding:6px 8px;color:var(--text);border:1px solid transparent;border-radius:11px;background:transparent;text-align:left;font:inherit;cursor:pointer}
#themePicker .inj-theme-family>div.theme-list-unified>button:hover{background:var(--accent-soft)}
#themePicker .inj-theme-family>div.theme-list-unified>button.active{border-color:var(--line-strong);background:var(--accent-soft)}
#themePicker .inj-theme-family>div.theme-list-unified>button .theme-swatch{width:80px!important;flex:0 0 80px!important;height:48px!important;border-radius:9px!important;display:block;box-shadow:inset 0 0 0 1px rgba(127,147,161,.24)}
#themePicker .inj-theme-family>div.theme-list-unified>button span{font-size:12px;font-weight:550}
#themePicker .inj-theme-family>summary:focus-visible,#themePicker .inj-theme-family button:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
#themePicker .inj-theme-family>summary .inj-family-count{font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums}
#themePicker .inj-theme-family[data-family="signature"] .inj-family-illustration{color:#63ddeb}
#themePicker .inj-theme-family[data-family="minimal"] .inj-family-illustration{color:#b8c1c8}
#themePicker .inj-theme-family[data-family="crystal"] .inj-family-illustration{color:#89cce2}
#themePicker .inj-theme-family[data-family="digital"] .inj-family-illustration{color:#71f0d4}
#themePicker .inj-theme-family[data-family="classic"] .inj-family-illustration{color:#d4b88b}
@media(max-width:420px){#themePicker .inj-theme-family>summary{padding:9px 10px}#themePicker .inj-theme-family>div.theme-list-unified>button .theme-swatch{flex-basis:73px!important;width:73px!important;height:44px!important}}
