/* SVG micro-motion: one quiet motion in each financial instrument. */
.inj-pro-icon-frame {opacity:.68;stroke-width:1.65px}
.inj-pro-icon-muted {opacity:.44}
.inj-pro-icon-detail {stroke-width:1.75px;opacity:.92}
.inj-pro-icon-bright {stroke-width:2.3px}
.inj-pro-icon-accent {fill:currentColor;stroke:none}
.inj-pro-icon-dashboard .inj-pro-dash-trace {
  stroke-dasharray:63 8;
  animation:injProTrace 4.4s ease-in-out infinite;
}
.inj-pro-icon-dashboard .inj-pro-dash-point {
  transform-origin:50px 21px;
  animation:injProDot 3.2s ease-in-out infinite;
}
.inj-pro-icon-live .inj-pro-live-wave {
  stroke-dasharray:8 6;
  animation:injProLivePulse 4s linear infinite;
}
.inj-pro-icon-live .inj-pro-live-beacon {
  transform-origin:51px 32px;
  animation:injProDot 3.1s ease-in-out infinite;
}
.inj-pro-icon-live .inj-pro-live-scan {
  stroke-width:1px;
  animation:injProScan 4.2s ease-in-out infinite;
}
.inj-pro-icon-treasury .inj-pro-vault-rotor {
  transform-origin:32px 33px;
  animation:injProVaultTurn 7.5s ease-in-out infinite;
}
.inj-pro-icon-treasury .inj-pro-vault-led {
  animation:injProVaultLED 3.8s ease-in-out infinite;
}
@keyframes injProTrace{
  0%,100%{stroke-dashoffset:0;opacity:.85}
  50%{stroke-dashoffset:-11;opacity:1}
}
@keyframes injProDot{
  0%,100%{opacity:.55;transform:scale(.76)}
  50%{opacity:1;transform:scale(1.18)}
}
@keyframes injProLivePulse{
  to{stroke-dashoffset:-28}
}
@keyframes injProScan{
  0%,100%{opacity:.12;transform:translateY(-5px)}
  48%{opacity:.52;transform:translateY(8px)}
}
@keyframes injProVaultTurn{
  0%,12%{transform:rotate(0)}
  55%,70%{transform:rotate(50deg)}
