/* ./inj-theme-canvas-sync-20261105.css?v=theme-continuity1 */
/* INJ Node · instant palette continuity · 2026-11-05
   One chosen theme controls the page canvas, Home top, and status-tint
   fallback. No fake status overlays or changes to touch/scroll/safe-area. */
html[data-theme][data-inj-page="index"]{
  --inj-native-status-tone:var(--theme-canvas,var(--bg,#07121b))!important;
  --inj-native-top-tone:var(--theme-canvas,var(--bg,#07121b))!important;
  background-color:var(--theme-canvas,var(--bg,#07121b))!important;
}
/* The old Home overlay had its OWN full-screen gradient, with a different
   top origin from html, which painted an apparent previous-theme band.
   Paint the selected theme just once, on the viewport root. */
html[data-theme][data-inj-page="index"] body > #entryGate#entryGate.entry-gate,
html[data-theme][data-inj-page="index"] body > #entryGate#entryGate.entry-gate.visible,
html[data-theme][data-inj-page="index"] body > #entryGate#entryGate.entry-gate > .entry-gate-shell:not(.first-access),
html[data-theme][data-inj-page="index"] body > .app-shell{
  background-color:transparent!important;
  background-image:none!important;
}
/* Keep the topmost Home elements clear, not a hard rectangular paint.
   Menu surfaces and full-screen destinations retain their proper panels. */
html[data-theme][data-inj-page="index"] body #entryGate
:is(.entry-home-top,.home-safe-heading.inj-terminal-hero-arranged){
  background-color:transparent!important;
  background-image:none!important;
}
/* The Lite surface owns its design, but its top fill must use this theme's
   current canvas rather than a persisted solid status color. */
html[data-theme][data-inj-page="index"] body #injLightHome .inj-light-screen{
  --inj-native-status-tone:var(--theme-canvas,var(--bg,#07121b));
  --inj-native-top-tone:var(--theme-canvas,var(--bg,#07121b));
}


/* ./inj-home-native-edge-20261105.css?v=fullbleed-native-edge1 */
/* INJ NODE · iPhone native edge / seamless Home · 2026-11-05.
   The existing status palette CSS added a dark, opaque 185px top fade.
   Use one continuous, actual theme canvas. Do not make an extra status
   slab or move the native Home header into the iPhone sensor cutout. */
@media (max-width:900px), (hover:none) and (pointer:coarse) {
  html[data-inj-page="index"][data-theme] {
    --inj-native-status-tone:var(--theme-canvas,var(--bg,#060b11))!important;
    --inj-native-top-tone:var(--theme-canvas,var(--bg,#060b11))!important;
    background-color:var(--theme-canvas,var(--bg,#060b11))!important;
    background-image:var(--page-gradient,none)!important;
    background-repeat:no-repeat!important;
    background-position:center top!important;
    background-size:100% 100%!important;
    background-attachment:fixed!important;
  }
  html[data-inj-page="index"][data-theme] body {
    background-color:transparent!important;
    background-image:none!important;
  }
  /* Old edge sampling used a z-index above every screen surface.
     Native iOS draws its own status icons; never cover them with a
     synthetic strip, even a 7px strip. */
  html[data-inj-page="index"] #injNativeChromeEdgeSample {
    display:none!important;
    visibility:hidden!important;
  }
  html[data-inj-page="index"][data-theme] body > #entryGate.entry-gate,
  html[data-inj-page="index"][data-theme] body > #entryGate.entry-gate.visible,
  html[data-inj-page="index"][data-theme] body > #entryGate.entry-gate > .entry-gate-shell:not(.first-access) {
    background-color:transparent!important;
    background-image:none!important;
  }
  html[data-inj-page="index"][data-theme] body #entryGate
  :is(.entry-home-top,.home-safe-heading.inj-terminal-hero-arranged) {
    background:transparent!important;
    -webkit-mask-image:none!important;
    mask-image:none!important;
  }
  /* Keep the genuine iPhone safe-area inset in the content layout.
     Do not overlay the hamburger, title or Pro mode button. */
  html[data-inj-page="index"][data-theme] body.entry-gate-open
  #entryGate.entry-gate.visible > .entry-gate-shell:not(.first-access) {
    padding-top:max(6px,env(safe-area-inset-top,0px))!important;
  }
}


/* ./dashboard-theme-canvas-20261105.css?v=dashboard-theme-art1 */
/* INJ NODE · Dashboard native theme artwork · 2026-11-05
   The Home uses an ambient SVG compositor inside #entryGate, which is
   hidden in Dashboard. Without that layer the Dashboard showed only
   a flat page-gradient, giving the impression of an opaque rectangle
   below the data cards.
   Reuse the *selected theme's existing artwork* on the one viewport root,
   not a second element between the canvas and information cards. */
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]{
  background-color:var(--theme-canvas,var(--bg,#061019))!important;
  background-image:var(--inj-theme-art,none),var(--page-gradient,none)!important;
  background-repeat:repeat-x,no-repeat!important;
  background-size:100vw 100%,100% 100%!important;
  background-position:0 50%,center center!important;
  background-attachment:fixed,fixed!important;
  /* The Dashboard does not inherit the Home background-animation override. */
}
@keyframes inj-dashboard-theme-flow {
  from {background-position:0 50%,center center}
  to {background-position:-100vw 50%,center center}
}
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme][data-inj-theme-motion="dynamic"]{
  animation:inj-dashboard-theme-flow var(--inj-signature-duration,34s) linear infinite!important;
}
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]:not([data-inj-theme-motion="dynamic"]){
  animation:none!important;
}
@media(prefers-reduced-motion:reduce){
  html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]{
    animation:none!important;
    background-position:0 50%,center center!important;
  }
}
/* Only *structural* surfaces become transparent. Keep the existing filled
   Dashboard data cards, wallet tiles, market panels and navigation controls
   completely unchanged, including their borders, typography and gradients. */
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]
 body.dashboard-scroll-ready:not(.entry-gate-open) > .app-shell,
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]
 body.dashboard-scroll-ready:not(.entry-gate-open) > .app-shell > main#top,
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]
 body.dashboard-scroll-ready:not(.entry-gate-open) > .app-shell > main#top >
 :is(.overview-grid,.metrics-grid,.analytics-grid,.detail-grid),
html[data-inj-page="index"][data-inj-scroll="dashboard"][data-theme]
 body.dashboard-scroll-ready:not(.entry-gate-open) > .app-shell > main#top >
 .wallet-dock > .saved-wallets {
  background:transparent!important;
  background-image:none!important;
  background-color:transparent!important;
  -webkit-backdrop-filter:none!important;
  backdrop-filter:none!important;
}
/* Dashboard page surfaces never hide the root art. No change to the Home
   scrollport: it keeps its existing GPU-composited artwork and navigation. */
